from __future__ import annotations

import re
import shutil
from pathlib import Path

from reportgen import stp
from reportgen.document import Block

SPECIAL = {
    "\\": r"\textbackslash{}",
    "&": r"\&",
    "%": r"\%",
    "$": r"\$",
    "#": r"\#",
    "_": r"\_",
    "{": r"\{",
    "}": r"\}",
    "~": r"\textasciitilde{}",
    "^": r"\textasciicircum{}",
}
INLINE_RE = re.compile(r"(`[^`]+`|\*[^*]+\*)")

PREAMBLE = r"""\documentclass[a4paper,14pt]{extarticle}
\usepackage{fontspec}
\IfFontExistsTF{Times New Roman}{\setmainfont{Times New Roman}}{\setmainfont{Liberation Serif}}
\IfFontExistsTF{Courier New}{\setmonofont{Courier New}}{\setmonofont{Liberation Mono}}
\usepackage[russian]{babel}
\usepackage[a4paper,left=%(left)smm,right=%(right)smm,top=%(top)smm,bottom=%(bottom)smm]{geometry}
\usepackage{graphicx}
\usepackage{longtable}
\usepackage{array}
\usepackage{fancyhdr}
\usepackage{tocloft}
\usepackage{fvextra}
\usepackage[hidelinks]{hyperref}

\fontsize{14}{18}\selectfont
\setlength{\parindent}{%(indent)scm}
\setlength{\parskip}{0pt}
\setlength{\baselineskip}{18pt}
\raggedbottom
\sloppy

\pagestyle{fancy}
\fancyhf{}
\fancyfoot[R]{\thepage}
\renewcommand{\headrulewidth}{0pt}

\renewcommand{\cftsecfont}{\normalfont}
\renewcommand{\cftsubsecfont}{\normalfont}
\renewcommand{\cftsecpagefont}{\normalfont}
\renewcommand{\cftsecleader}{\cftdotfill{\cftdotsep}}
\renewcommand{\cftsubsecleader}{\cftdotfill{\cftdotsep}}
\setlength{\cftbeforesecskip}{0pt}
\setlength{\cftbeforesubsecskip}{0pt}

\newcommand{\stpchapter}[2]{\clearpage\noindent\hspace{\parindent}\textbf{#1 #2}\par\vspace{\baselineskip}\addcontentsline{toc}{section}{#1 #2}}
\newcommand{\stpsection}[2]{\noindent\hspace{\parindent}\textbf{#1 #2}\par\vspace{\baselineskip}\addcontentsline{toc}{subsection}{#1 #2}}
\newcommand{\stpsubsection}[2]{\noindent\hspace{\parindent}\textbf{#1 #2}\par\vspace{\baselineskip}}
\newcommand{\stpplain}[1]{\clearpage\begin{center}\textbf{#1}\end{center}\vspace{\baselineskip}\addcontentsline{toc}{section}{#1}}
\newcommand{\stpappendix}[2]{\clearpage\begin{center}\textbf{ПРИЛОЖЕНИЕ #1}\\\textbf{#2}\end{center}\vspace{\baselineskip}\addcontentsline{toc}{section}{ПРИЛОЖЕНИЕ #1 #2}}
\newcommand{\stpdash}{\textendash}

\begin{document}
"""


def escape(text: str) -> str:
    return "".join(SPECIAL.get(ch, ch) for ch in text)


def inline(text: str) -> str:
    out = []
    for part in INLINE_RE.split(text):
        if not part:
            continue
        if part.startswith("`") and part.endswith("`"):
            out.append(r"\texttt{" + escape(part[1:-1]) + "}")
        elif part.startswith("*") and part.endswith("*") and len(part) > 2:
            out.append(r"\textit{" + escape(part[1:-1]) + "}")
        else:
            out.append(escape(part))
    return "".join(out)


def _title_page(meta: dict) -> str:
    lines = [r"\begin{titlepage}", r"\centering"]

    def row(text: str, bold: bool = False, gap: int = 0) -> None:
        if not text:
            return
        body = inline(text)
        lines.append((r"\textbf{%s}" % body if bold else body) + r"\par")
        if gap:
            lines.append(r"\vspace{%d\baselineskip}" % gap)

    row(meta.get("ministry", "Министерство образования Республики Беларусь"))
    row(meta.get("university", "Учреждение образования «Белорусский государственный университет информатики и радиоэлектроники»"), gap=1)
    row(meta.get("faculty", ""))
    row(meta.get("department", ""), gap=3)
    row(meta.get("work_type", "ПОЯСНИТЕЛЬНАЯ ЗАПИСКА"), bold=True)
    if meta.get("discipline"):
        row(f"по дисциплине «{meta['discipline']}»", gap=1)
    row(f"Тема: {meta.get('title', '')}", bold=True, gap=4)
    lines.append(r"\begin{flushright}\begin{minipage}{0.5\textwidth}\raggedright")
    for label, key in (("Студент гр. ", "group"), ("Выполнил: ", "student"), ("Руководитель: ", "supervisor")):
        if meta.get(key):
            lines.append(inline(f"{label}{meta[key]}") + r"\par")
    lines.append(r"\end{minipage}\end{flushright}")
    lines.append(r"\vfill")
    lines.append(inline(f"{meta.get('city', 'Минск')} {meta.get('year', '')}"))
    lines.append(r"\end{titlepage}")
    return "\n".join(lines)


def _heading(block: Block) -> str:
    title = escape(block.text)
    if block.appendix:
        return rf"\stpappendix{{{block.number}}}{{{title}}}"
    if block.level == 1 and not block.numbered:
        return rf"\stpplain{{{title}}}"
    command = {1: "stpchapter", 2: "stpsection", 3: "stpsubsection"}[block.level]
    return rf"\{command}{{{block.number}}}{{{title}}}"


def _table(block: Block) -> str:
    rows = block.rows
    columns = max(len(r) for r in rows)
    spec = "|" + "|".join([r">{\raggedright\arraybackslash}p{%.3f\textwidth}" % (0.98 / columns)] * columns) + "|"
    out = []
    if block.caption:
        out.append(r"\noindent " + escape(stp.table_caption(block.number, block.caption)) + r"\par\nopagebreak")
    out.append(r"\begin{longtable}{%s}" % spec)
    out.append(r"\hline")
    for index, row in enumerate(rows):
        cells = [inline(row[c]) if c < len(row) else "" for c in range(columns)]
        if index == 0:
            cells = [r"\centering\textbf{%s}" % c if False else c for c in cells]
        out.append(" & ".join(cells) + r" \\ \hline")
        if index == 0:
            out.append(r"\endhead")
    out.append(r"\end{longtable}")
    out.append(r"\vspace{\baselineskip}")
    return "\n".join(out)


def _figure(block: Block, build_dir: Path, base: Path, counter: int) -> str:
    source = (base / block.path).resolve()
    if not source.is_file():
        return rf"\noindent\textit{{[нет файла: {escape(block.path)}]}}\par"
    target_dir = build_dir / "figures"
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / f"fig{counter}{source.suffix.lower()}"
    shutil.copyfile(source, target)
    caption = escape(stp.figure_caption(block.number, block.caption))
    return (
        "\\begin{center}\n"
        f"\\includegraphics[width=\\textwidth,height=0.6\\textheight,keepaspectratio]{{figures/{target.name}}}\\par\n"
        f"{caption}\n"
        "\\end{center}\n\\vspace{\\baselineskip}"
    )


def _code(block: Block) -> str:
    out = []
    if block.caption:
        out.append(r"\noindent " + escape(stp.listing_caption(block.number, block.caption)) + r"\par\nopagebreak")
    out.append(r"\begin{Verbatim}[fontsize=\small,breaklines=true,breakanywhere=true]")
    out.append(block.text)
    out.append(r"\end{Verbatim}")
    out.append(r"\vspace{\baselineskip}")
    return "\n".join(out)


def render(blocks: list[Block], meta: dict, base: Path, build_dir: Path) -> Path:
    build_dir.mkdir(parents=True, exist_ok=True)
    parts = [
        PREAMBLE
        % {
            "left": stp.MARGIN_LEFT_MM,
            "right": stp.MARGIN_RIGHT_MM,
            "top": stp.MARGIN_TOP_MM,
            "bottom": stp.MARGIN_BOTTOM_MM,
            "indent": stp.PARAGRAPH_INDENT_CM,
        }
    ]
    if meta.get("title_page", True):
        parts.append(_title_page(meta))
    if meta.get("toc", True):
        parts.append(
            r"\clearpage\begin{center}\textbf{СОДЕРЖАНИЕ}\end{center}\vspace{\baselineskip}"
            "\n" r"\renewcommand{\contentsname}{}\tableofcontents"
        )

    figures = 0
    for block in blocks:
        if block.kind == "heading":
            parts.append(_heading(block))
        elif block.kind == "paragraph":
            parts.append(inline(block.text) + "\n")
        elif block.kind == "list":
            for line in stp.list_items(block.items):
                parts.append(inline(line) + "\n")
        elif block.kind == "figure":
            figures += 1
            parts.append(_figure(block, build_dir, base, figures))
        elif block.kind == "table":
            parts.append(_table(block))
        elif block.kind == "code":
            parts.append(_code(block))
    parts.append(r"\end{document}")

    tex = build_dir / "note.tex"
    tex.write_text("\n\n".join(parts) + "\n", encoding="utf-8")
    return tex

