    formats: tuple[str, ...] = ALL_FORMATS,
) -> dict[str, Path]:
    blocks = repository.load_blocks()
    if not blocks:
        raise EmptyReportError("В работе нет разделов: сначала выполните «write» или добавьте файлы в content/")
    meta = repository.read_meta()
    output_dir = repository.root / OUTPUT_DIR
    results: dict[str, Path] = {}

    if "docx" in formats:
        results["docx"] = renderers["docx"].render(blocks, meta, repository.root, output_dir / "note.docx")
    if "tex" in formats or "pdf" in formats:
        tex_file = renderers["tex"].render(blocks, meta, repository.root, output_dir / "tex" / "note.tex")
        if "tex" in formats:
            results["tex"] = tex_file
        if "pdf" in formats:
            results["pdf"] = pdf_compiler.compile(tex_file, output_dir / "note.pdf")
    return results

from __future__ import annotations

from dataclasses import dataclass

from reportgen.application.ports import ProjectRepository, ReferenceLibrary
from reportgen.domain import overlap
from reportgen.domain.lint_rules import Issue, check_blocks


def lint_report(repository: ProjectRepository) -> list[Issue]:
    return check_blocks(repository.load_blocks())


@dataclass(frozen=True)
class OverlapReport:
    matches: list[overlap.Match]
    share: float


def check_overlap(paragraphs: list[str], library: ReferenceLibrary, threshold: float = overlap.DEFAULT_THRESHOLD) -> OverlapReport:
    index = library.documents()
    return OverlapReport(overlap.find_matches(paragraphs, index, threshold), overlap.overall_share(paragraphs, index))

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Mapping

from reportgen.application.ports import ScreenshotTaker


@dataclass(frozen=True)
class CaptureResult:
    name: str
    file: str
    caption: str
    ok: bool
    error: str = ""


def capture_all(
    items: list[dict],
    takers: Mapping[str, ScreenshotTaker],
    output_dir: Path,
    project_root: Path,
) -> list[CaptureResult]:
    """Снимает все элементы плана; сбой одного элемента не прерывает остальные."""
    return [_capture_one(item, takers, output_dir, project_root) for item in items]


def _capture_one(item: dict, takers: Mapping[str, ScreenshotTaker], output_dir: Path, project_root: Path) -> CaptureResult:
    name = item["name"]
    caption = item.get("caption", name)
    file = f"screenshots/{name}.png"
    taker = takers.get(item["kind"])
    if taker is None:
        return CaptureResult(name, file, caption, False, f"Неизвестный вид: {item['kind']}")
    try:
        taker.take(item, output_dir / f"{name}.png", project_root)
    except Exception as error:  # адаптеры бросают разные исключения: сбой снимка не должен ронять весь план
        return CaptureResult(name, file, caption, False, str(error))
    return CaptureResult(name, file, caption, True)

