def _heading(block: Block) -> str:
    title = escape(block.text)
    if block.appendix:
        return rf"\stpappendix{{{block.number}}}{{{title}}}"
    if block.level == 1 and not block.numbered:
        return rf"\stpplain{{{title}}}"
    command = {1: "stpchapter", 2: "stpsection", 3: "stpsubsection"}[block.level]
    return rf"\{command}{{{block.number}}}{{{title}}}"


def _table(block: Block) -> str:
    rows = block.rows
    columns = max(len(r) for r in rows)
    spec = "|" + "|".join([r">{\raggedright\arraybackslash}p{%.3f\textwidth}" % (0.98 / columns)] * columns) + "|"
    out = []
    if block.caption:
        out.append(r"\noindent " + escape(stp.table_caption(block.number, block.caption)) + r"\par\nopagebreak")
    out.append(r"\begin{longtable}{%s}" % spec)
    out.append(r"\hline")
    for index, row in enumerate(rows):
        cells = [inline(row[c]) if c < len(row) else "" for c in range(columns)]
        out.append(" & ".join(cells) + r" \\ \hline")
        if index == 0:
            out.append(r"\endhead")
    out.append(r"\end{longtable}")
    out.append(r"\vspace{\baselineskip}")
    return "\n".join(out)


def _figure(block: Block, build_dir: Path, base: Path, counter: int) -> str:
    source = (base / block.path).resolve()
    if not source.is_file():
        return rf"\noindent\textit{{[нет файла: {escape(block.path)}]}}\par"
    target_dir = build_dir / "figures"
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / f"fig{counter}{source.suffix.lower()}"
    shutil.copyfile(source, target)
    caption = escape(stp.figure_caption(block.number, block.caption))
    return (
        "\\begin{center}\n"
        f"\\includegraphics[width=\\textwidth,height=0.6\\textheight,keepaspectratio]{{figures/{target.name}}}\\par\n"
        f"{caption}\n"
        "\\end{center}\n\\vspace{\\baselineskip}"
    )


def _code(block: Block) -> str:
    out = []
    if block.caption:
        out.append(r"\noindent " + escape(stp.listing_caption(block.number, block.caption)) + r"\par\nopagebreak")
    out.append(r"\begin{Verbatim}[fontsize=\small,breaklines=true,breakanywhere=true]")
    out.append(block.text)
    out.append(r"\end{Verbatim}")
    out.append(r"\vspace{\baselineskip}")
    return "\n".join(out)


def render(blocks: list[Block], meta: dict, base: Path, build_dir: Path) -> Path:
    build_dir.mkdir(parents=True, exist_ok=True)
    parts = [
        PREAMBLE
        % {
            "left": stp.MARGIN_LEFT_MM,
            "right": stp.MARGIN_RIGHT_MM,
            "top": stp.MARGIN_TOP_MM,
            "bottom": stp.MARGIN_BOTTOM_MM,
            "indent": stp.PARAGRAPH_INDENT_CM,
        }
    ]
    if meta.get("title_page", True):
        parts.append(_title_page(meta))
    if meta.get("toc", True):
        parts.append(
            r"\clearpage\begin{center}\textbf{СОДЕРЖАНИЕ}\end{center}\vspace{\baselineskip}"
            "\n" r"\renewcommand{\contentsname}{}\tableofcontents"
        )

    figures = 0
    for block in blocks:
        if block.kind is Kind.HEADING:
            parts.append(_heading(block))
        elif block.kind is Kind.PARAGRAPH:
            parts.append(inline(block.text) + "\n")
        elif block.kind is Kind.LIST:
            for line in stp.list_items(block.items):
                parts.append(inline(line) + "\n")
        elif block.kind is Kind.FIGURE:
            figures += 1
            parts.append(_figure(block, build_dir, base, figures))
        elif block.kind is Kind.TABLE:
            parts.append(_table(block))
        elif block.kind is Kind.CODE:
            parts.append(_code(block))

