from __future__ import annotations

import base64
import json
import os
from pathlib import Path

from cryptography.fernet import Fernet, InvalidToken
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt

from reportgen.domain.personal import PersonalProfile
from reportgen.infrastructure.settings import home

VAULT_FILE = "profile.enc"
UNLOCK_FILE = "unlock.txt"
UNLOCK_ENV = "REPORTGEN_UNLOCK_FILE"
SALT_BYTES = 16
SCRYPT_N, SCRYPT_R, SCRYPT_P = 2**15, 8, 1
MIN_PASSWORD_CHARS = 8


def _derive_key(password: str, salt: bytes) -> bytes:
    kdf = Scrypt(salt=salt, length=32, n=SCRYPT_N, r=SCRYPT_R, p=SCRYPT_P)
    return base64.urlsafe_b64encode(kdf.derive(password.encode("utf-8")))


def unlock_file() -> Path:
    return Path(os.environ.get(UNLOCK_ENV) or UNLOCK_FILE)


def read_password(path: Path | None = None) -> str:
    """Первая строка файла, не начинающаяся с «#»; пустая строка, если файла или пароля нет."""
    target = path or unlock_file()
    if not target.is_file():
        return ""
    for line in target.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            return stripped
    return ""


class EncryptedProfileVault:
    def __init__(self, path: Path | None = None) -> None:
        self.path = path or home() / VAULT_FILE

    def exists(self) -> bool:
        return self.path.is_file()

    def save(self, profile: PersonalProfile, password: str) -> None:
        if len(password) < MIN_PASSWORD_CHARS:
            raise ValueError(f"Пароль должен быть не короче {MIN_PASSWORD_CHARS} символов")
        salt = os.urandom(SALT_BYTES)
        token = Fernet(_derive_key(password, salt)).encrypt(json.dumps(profile.to_dict(), ensure_ascii=False).encode("utf-8"))
        payload = {"salt": base64.b64encode(salt).decode("ascii"), "token": token.decode("ascii")}
        self.path.write_text(json.dumps(payload), encoding="utf-8")

    def open(self, password: str) -> PersonalProfile | None:
        """Расшифровывает данные паролем. Сравнений нет: без верного пароля расшифровка просто не удаётся."""
        try:
            payload = json.loads(self.path.read_text(encoding="utf-8"))
            key = _derive_key(password, base64.b64decode(payload["salt"]))
            return PersonalProfile.from_dict(json.loads(Fernet(key).decrypt(payload["token"].encode("ascii"))))
        except (OSError, ValueError, KeyError, InvalidToken):
            return None

    def open_with_file(self, path: Path | None = None) -> PersonalProfile | None:
        password = read_password(path)
        return self.open(password) if password else None

