import re
import sys
from collections import Counter

from docx import Document

sys.stdout.reconfigure(encoding="utf-8")
d = Document(sys.argv[1])

print("--- heading styles (effective settings)")
for name in ("Heading 1", "Heading 2", "Heading 3"):
    s = d.styles[name]
    f = s.paragraph_format
    print(f"{name}: font={s.font.name} size={s.font.size.pt if s.font.size else None} bold={s.font.bold} italic={s.font.italic} color={s.font.color.rgb if s.font.color and s.font.color.type else None} "
          f"align={f.alignment} indent={f.first_line_indent} before={f.space_before} after={f.space_after} keep_next={f.keep_with_next} page_break_before={f.page_break_before} line={f.line_spacing_rule}/{f.line_spacing}")

print("--- headings in body (direct formatting)")
seen = Counter()
for p in d.paragraphs:
    if p.style.name.startswith("Heading"):
        runs_bold = {r.bold for r in p.runs}
        key = (p.style.name, str(p.alignment), str(p.paragraph_format.first_line_indent), tuple(sorted(map(str, runs_bold))))
        seen[key] += 1
for key, n in seen.most_common(8):
    print(n, key)

print("--- heading text case check")
bad = []
for p in d.paragraphs:
    if p.style.name == "Heading 1":
        letters = re.sub(r"[^А-Яа-яЁёA-Za-z]", "", re.sub(r"^\d+(\.\d+)*", "", p.text))
        if letters and not letters.isupper():
            bad.append(("H1 не прописными", p.text[:60]))
    if p.style.name == "Heading 2":
        body = re.sub(r"^\d+(\.\d+)*\s*", "", p.text)
        if body.isupper() and len(body) > 4:
            bad.append(("H2 прописными", p.text[:60]))
    if p.text.rstrip().endswith("."):
        if p.style.name.startswith("Heading"):
            bad.append(("точка в конце заголовка", p.text[:60]))
for item in bad[:10]:
    print(item)
print("heading issues:", len(bad))

print("--- table captions: alignment / position vs table")
body = d.element.body
children = list(body.iterchildren())
captions = {p._p: p for p in d.paragraphs if re.match(r"^Таблица\s", p.text.strip())}
align = Counter()
position = Counter()
for index, child in enumerate(children):
    if child in captions:
        align[str(captions[child].alignment)] += 1
        nxt = children[index + 1] if index + 1 < len(children) else None
        position["за подписью идёт таблица" if nxt is not None and nxt.tag.endswith("}tbl") else "за подписью НЕ таблица"] += 1
print("table caption alignment:", dict(align))
print("after caption:", dict(position))

print("--- tables")
t_sizes = Counter()
t_align = Counter()
for t in d.tables:
    t_align[str(t.alignment)] += 1
    for row in t.rows[:2]:
        for c in row.cells:
            for p in c.paragraphs:
                for r in p.runs:
                    t_sizes[r.font.size.pt if r.font.size else "наследуется"] += 1
print("table alignment:", dict(t_align), "font sizes:", dict(t_sizes.most_common(4)))
print("table style names:", Counter(t.style.name if t.style else None for t in d.tables).most_common(3))

print("--- body paragraphs spacing (after fix)")
c = Counter()
for p in d.paragraphs:
    if len(p.text) > 80 and p.alignment is not None:
        f = p.paragraph_format
        c[(str(f.line_spacing_rule), str(f.line_spacing), str(f.space_after))] += 1
print(c.most_common(4))

print("--- figure paragraphs")
fig = Counter()
for p in d.paragraphs:
    if p._p.xpath(".//w:drawing"):
        fig[(str(p.alignment), str(p.paragraph_format.first_line_indent))] += 1
print("figure paragraph (align, indent):", dict(fig))

