DOWNLOADS = {"docx": "note.docx", "pdf": "note.pdf", "tex": "tex/note.tex"}
MAX_BODY_BYTES = 64 * 1024
PROVIDERS = {"cloud", "gemini", "local", "custom"}
JOB_OUTPUT_LIMIT = 60_000


