from pathlib import Path


def read(path: str) -> str:
    return Path(path).read_bytes().decode("utf-8").replace("\r\n", "\n")


def write(path: str, text: str) -> None:
    Path(path).write_bytes(text.encode("utf-8"))


def replace_once(source: str, old: str, new: str) -> str:
    assert source.count(old) == 1, old
    return source.replace(old, new)


prompts = read("src/reportgen/data/guidelines/prompts.yaml")
prompts = replace_once(
    prompts,
    "review: |",
    """revise: |
  Исправь текст раздела «{title}» по замечаниям автоматической проверки.

  Замечания:
  {issues}

  Правила исправления:
  - сохрани смысл, факты, термины и метки в фигурных скобках;
  - метку [УТОЧНИТЬ: …] убери, если нужный факт есть в сведениях ниже или раздел без него остаётся полным (напиши нейтрально, без догадок);
    оставь метку только тогда, когда без этого факта раздел по существу неполон;
  - если нет ссылки на рисунок или таблицу, добавь её в подходящее место текста;
  - не добавляй новых фактов, которых нет в сведениях.
  Верни только исправленный текст раздела без заголовка.

  Текст раздела:
  {body}

  Сведения:
  {facts}

review: |""",
)
write("src/reportgen/data/guidelines/prompts.yaml", prompts)

domain = read("src/reportgen/domain/prompts.py")
domain = replace_once(domain, "    rewrite: str\n    review: str\n", "    rewrite: str\n    revise: str\n    review: str\n")
domain = replace_once(
    domain,
    "    def review_prompt(self, remarks: str, document: str) -> str:",
    "    def revise_prompt(self, title: str, issues: list[str], body: str, facts: str) -> str:\n"
    "        return self.revise.format(title=title, issues=\"\\n\".join(f\"- {issue}\" for issue in issues), body=body, facts=facts or \"(сведений нет)\")\n\n"
    "    def review_prompt(self, remarks: str, document: str) -> str:",
)
write("src/reportgen/domain/prompts.py", domain)

library = read("src/reportgen/infrastructure/prompt_library.py")
library = replace_once(library, '        rewrite=prompts["rewrite"],\n', '        rewrite=prompts["rewrite"],\n        revise=prompts["revise"],\n')
write("src/reportgen/infrastructure/prompt_library.py", library)
print("revise prompt added")

