    $document = $word.Documents.Open((Resolve-Path $InputFile).Path, $false, $true)
    $document.Repaginate()
    $splits = 0
    while ($splits -lt $MaxSplits -and (Split-OneTable $document)) {
        $splits++
        $document.Repaginate()
    }
    foreach ($contents in $document.TablesOfContents) { $contents.Update() }
    $document.Fields.Update() | Out-Null
    $document.Repaginate()
    foreach ($contents in $document.TablesOfContents) { $contents.UpdatePageNumbers() }
    $document.SaveAs2([ref]$OutputDocx, [ref]$wdFormatXMLDocument)
    $document.ExportAsFixedFormat($OutputPdf, $wdExportFormatPDF)
    Write-Output ([regex]::Unescape('__PAGES__') + ": " + $document.ComputeStatistics($wdStatisticPages) + "; continuation splits: $splits")
    $document.Close(0)
}
finally {
    $word.Quit()
}
'''
script = (
    script.replace("__CONTINUATION__", CONTINUATION)
    .replace("__TABLE_LOWER__", TABLE_WORD_LOWER)
    .replace("__TABLE__", TABLE_WORD)
    .replace("__PAGES__", PAGES)
)
Path("scripts/word_finalize.ps1").write_bytes(("﻿" + script).encode("utf-8"))
print("script written with BOM")

